20	 * @param {number} v 新值
21	 * @param {number} max 窗口最大长度
22	 * @returns {number[]} 新窗口数组
23	 */
24	function pushWindow(arr, v, max) {
25	  const next = arr.concat([v]);
26	  return next.length > max ? next.slice(next.length - max) : next;
27	}
