30	 * 计算窗口的最小 / 均值（四舍五入）/ 最大；空窗口返回全 0。
31	 * @param {number[]} arr 数值窗口
32	 * @returns {{min: number, avg: number, max: number}} 统计结果
33	 */
34	function stats(arr) {
35	  if (!arr || arr.length === 0) {
36	    return { min: 0, avg: 0, max: 0 };
37	  }
38	  let min = arr[0];
39	  let max = arr[0];
40	  let sum = 0;
41	  for (let i = 0; i < arr.length; i++) {
42	    const v = arr[i];
43	    if (v < min) min = v;
44	    if (v > max) max = v;
45	    sum += v;
46	  }
47	  return { min, max, avg: Math.round(sum / arr.length) };
