### 2. 传感器接口封装层

```javascript
// src/common/services/sensor.js
import sensor from '@system.sensor'
import { MOCK_CONFIG } from '../../config/mock-config'
import { MockSensor } from '../mock/mock-sensor'

class SensorService {
  constructor() {
    this.subscribers = []
    this.mockSensor = new MockSensor()
    this.isRunning = false
  }

  /**
   * 订阅加速度计数据
   * @param {Function} callback - 回调函数，参数: { x, y, z, timestamp }
   * @param {string} interval - 采样频率: 'game' | 'ui' | 'normal'
   */
  subscribeAccelerometer(callback, interval = 'game') {
    this.subscribers.push(callback)

    if (this.isRunning) return

    if (MOCK_CONFIG.useMock) {
      // 使用 Mock 数据
      this.mockSensor.start((data) => {
        this.notifySubscribers(data)
      }, interval)
    } else {
      // 使用真实 API
      sensor.subscribeAccelerometer({
        interval: interval,
        callback: (data) => {
          this.notifySubscribers({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        },
        fail: (data, code) => {
          console.error('Accelerometer error:', code)
        }
      })
    }
    this.isRunning = true
  }

  /**
   * 取消订阅
   */
  unsubscribeAccelerometer(callback) {
    this.subscribers = this.subscribers.filter(cb => cb !== callback)

    if (this.subscribers.length === 0) {
      if (MOCK_CONFIG.useMock) {
        this.mockSensor.stop()
      } else {
        sensor.unsubscribeAccelerometer()
      }
      this.isRunning = false
    }
  }

  /**
   * 通知所有订阅者
   */
  notifySubscribers(data) {
    this.subscribers.forEach(cb => cb(data))
  }
}

// 单例模式
export const sensorService = new SensorService()
```

### 3. Mock 传感器数据生成器

```javascript
// src/common/mock/mock-sensor.js
import { MOCK_CONFIG } from '../../config/mock-config'

// 预设的模拟数据场景
const SCENARIOS = {
  // 正常坐姿数据
  normal: {
    baseX: 0.5,    // 轻微前倾
    baseY: 9.6,    // 接近重力加速度
    baseZ: 0.3,
    noise: 0.2     // 噪声范围
  },
  // 异常坐姿（驼背）
  bad_posture: {
    baseX: 3.5,    // 明显前倾
    baseY: 8.8,
    baseZ: 1.2,
    noise: 0.3
  },
  // 混合场景（正常+异常交替）
  mixed: null  // 动态生成
}

export class MockSensor {
  constructor() {
    this.timer = null
    this.dataIndex = 0
    this.phase = 0  // 用于混合场景的状态切换
  }

  /**
   * 启动模拟数据生成
   * @param {Function} callback - 数据回调
   * @param {string} interval - 采样频率
   */
  start(callback, interval = 'game') {
    const intervalMs = this.getIntervalMs(interval)

    this.timer = setInterval(() => {
      const data = this.generateData()
      callback(data)
    }, intervalMs)
  }

  /**
   * 停止模拟
   */
  stop() {
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
  }

  /**
   * 生成模拟数据
   */
  generateData() {
    let scenario = MOCK_CONFIG.scenario

    // 混合场景：交替产生正常和异常数据
    if (scenario === 'mixed') {
      this.phase += 0.02
      const ratio = (Math.sin(this.phase) + 1) / 2  // 0-1 之间波动
      scenario = ratio > 0.5 ? 'normal' : 'bad_posture'
    }

    const config = SCENARIOS[scenario] || SCENARIOS.normal

    // 添加噪声
    const noise = () => (Math.random() - 0.5) * config.noise * 2

    return {
      x: config.baseX + noise(),
      y: config.baseY + noise(),
      z: config.baseZ + noise(),
      timestamp: Date.now()
    }
  }

  /**
   * 根据采样频率返回毫秒间隔
   */
  getIntervalMs(interval) {
    switch (interval) {
      case 'game': return 20    // 50Hz
      case 'ui': return 60      // ~16Hz
      case 'normal': return 200 // 5Hz
      default: return 20
    }
  }
}
```

### 4. 纯逻辑层（姿态判断算法）

```javascript
// src/common/core/posture.js
/**
 * 姿态判断算法 - 纯逻辑，无框架依赖
 * 可在 Node.js 环境下单元测试
 */

// 姿态状态常量
export const POSTURE_STATUS = {
  GOOD: 'good',           // 正常坐姿
  FAIR: 'fair',           // 轻微前倾
  POOR: 'poor',           // 严重前倾
  UNKNOWN: 'unknown'
}

/**
 * 从加速度数据计算俯仰角
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 俯仰角 (度)
 */
export function calculatePitch(ax, ay, az) {
  // 使用 atan2 计算俯仰角
  const pitch = Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * 180 / Math.PI
  return pitch
}

/**
 * 从加速度数据计算横滚角
 */
export function calculateRoll(ax, ay, az) {
  const roll = Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * 180 / Math.PI
  return roll
}

/**
 * 判断姿态状态
 * @param {number} pitch - 俯仰角
 * @param {Object} thresholds - 阈值配置
 * @returns {string} 姿态状态
 */
export function classifyPosture(pitch, thresholds = { fair: 15, poor: 30 }) {
  const absPitch = Math.abs(pitch)

  if (absPitch < thresholds.fair) {
    return POSTURE_STATUS.GOOD
  } else if (absPitch < thresholds.poor) {
    return POSTURE_STATUS.FAIR
  } else {
    return POSTURE_STATUS.POOR
  }
}

/**
 * 获取姿态对应的中文描述
 */
export function getPostureLabel(status) {
  const labels = {
    [POSTURE_STATUS.GOOD]: '正常',
    [POSTURE_STATUS.FAIR]: '注意',
    [POSTURE_STATUS.POOR]: '警告',
    [POSTURE_STATUS.UNKNOWN]: '未知'
  }
  return labels[status] || labels[POSTURE_STATUS.UNKNOWN]
}

/**
 * 获取姿态对应的颜色
 */
export function getPostureColor(status) {
  const colors = {
    [POSTURE_STATUS.GOOD]: '#4CAF50',    // 绿色
    [POSTURE_STATUS.FAIR]: '#FF9800',    // 橙色
    [POSTURE_STATUS.POOR]: '#F44336',    // 红色
    [POSTURE_STATUS.UNKNOWN]: '#9E9E9E'  // 灰色
  }
  return colors[status] || colors[POSTURE_STATUS.UNKNOWN]
}
```

### 5. 滤波器（互补滤波）

```javascript
// src/common/core/filter.js
/**
 * 互补滤波器 - 融合加速度计数据估算姿态
 * 纯逻辑，可独立测试
 */
export class ComplementaryFilter {
  constructor(alpha = 0.98) {
    this.alpha = alpha
    this.pitch = 0
    this.roll = 0
  }

  /**
   * 更新姿态估算
   * @param {number} ax - X轴加速度
   * @param {number} ay - Y轴加速度
   * @param {number} az - Z轴加速度
   * @returns {{ pitch: number, roll: number }}
   */
  update(ax, ay, az) {
    // 计算加速度计角度
    const pitchAcc = Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * 180 / Math.PI
    const rollAcc = Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * 180 / Math.PI

    // 低通滤波
    this.pitch = this.alpha * this.pitch + (1 - this.alpha) * pitchAcc
    this.roll = this.alpha * this.roll + (1 - this.alpha) * rollAcc

    return {
      pitch: this.pitch,
      roll: this.roll
    }
  }

  /**
   * 重置滤波器
   */
  reset() {
    this.pitch = 0
    this.roll = 0
  }
}
