/**
 * 常量定义
 */

// 姿态状态
export const POSTURE_STATUS = {
  GOOD: 'good',
  FAIR: 'fair',
  POOR: 'poor',
  UNKNOWN: 'unknown'
}

// 姿态状态颜色
export const POSTURE_COLORS = {
  [POSTURE_STATUS.GOOD]: '#4CAF50',
  [POSTURE_STATUS.FAIR]: '#FF9800',
  [POSTURE_STATUS.POOR]: '#F44336',
  [POSTURE_STATUS.UNKNOWN]: '#9E9E9E'
}

// 姿态状态标签（中文）
export const POSTURE_LABELS_ZH = {
  [POSTURE_STATUS.GOOD]: '坐姿良好',
  [POSTURE_STATUS.FAIR]: '注意坐姿',
  [POSTURE_STATUS.POOR]: '坐姿不佳',
  [POSTURE_STATUS.UNKNOWN]: '未知'
}

// 姿态状态标签（英文）
export const POSTURE_LABELS_EN = {
  [POSTURE_STATUS.GOOD]: 'Good Posture',
  [POSTURE_STATUS.FAIR]: 'Fair Posture',
  [POSTURE_STATUS.POOR]: 'Poor Posture',
  [POSTURE_STATUS.UNKNOWN]: 'Unknown'
}

// 默认阈值
export const DEFAULT_THRESHOLDS = {
  fair: 15,   // 轻微前倾阈值（度）
  poor: 30    // 严重前倾阈值（度）
}

// 存储键名
export const STORAGE_KEYS = {
  SETTINGS: 'posture_settings',
  DAILY_PREFIX: 'posture_daily_',
  SCORE: 'posture_score',
  SESSION: 'posture_session'
}

// 页面路由
export const ROUTES = {
  INDEX: '/pages/index',
  MONITOR: '/pages/monitor',
  REPORT: '/pages/report',
  SETTINGS: '/pages/settings'
}

/**
 * Mock 配置
 * 用于在模拟器中测试应用
 */

export const MOCK_CONFIG = {
  // 是否启用 Mock 模式
  useMock: true,

  // Mock 模式: 'interactive' | 'scenario' | 'timeline'
  mode: 'interactive',

  // 交互模式配置
  interactive: {
    currentPitch: 0,      // 当前模拟角度
    noiseLevel: 0.2       // 噪声级别 (0-1)
  },

  // 场景预设
  scenarios: {
    normal: {
      pitch: 5,
      noise: 0.2,
      label: '正常'
    },
    fair: {
      pitch: 22,
      noise: 0.3,
      label: '轻微前倾'
    },
    poor: {
      pitch: 45,
      noise: 0.4,
      label: '严重前倾'
    }
  },

  // 自动交替场景配置
  autoAlternate: {
    interval: 5000,       // 切换间隔 (ms)
    pattern: ['normal', 'normal', 'fair', 'poor']  // 循环模式
  },

  // Mock 采样频率 (ms)
  sampleInterval: 50     // 20Hz
}

// 切换到场景模式
export function setScenarioMode(scenarioName) {
  MOCK_CONFIG.mode = 'scenario'
  const scenario = MOCK_CONFIG.scenarios[scenarioName]
  if (scenario) {
    MOCK_CONFIG.interactive.currentPitch = scenario.pitch
    MOCK_CONFIG.interactive.noiseLevel = scenario.noise
  }
}

// 切换到交互模式
export function setInteractiveMode(pitch, noise) {
  MOCK_CONFIG.mode = 'interactive'
  MOCK_CONFIG.interactive.currentPitch = pitch
  MOCK_CONFIG.interactive.noiseLevel = noise || MOCK_CONFIG.interactive.noiseLevel
}

// 切换到自动交替模式
export function setAutoAlternateMode() {
  MOCK_CONFIG.mode = 'autoAlternate'
}

/**
 * Mock 传感器数据生成器
 * 用于在模拟器中模拟加速度计数据
 */

import { MOCK_CONFIG, setScenarioMode, setInteractiveMode, setAutoAlternateMode } from '../../config/mock-config'

export class MockSensor {
  constructor() {
    this.timer = null
    this.autoAlternateTimer = null
    this.autoAlternateIndex = 0
    this.onDataCallback = null
  }

  /**
   * 启动 Mock 数据生成
   * @param {Function} callback - 数据回调 { x, y, z, timestamp }
   * @param {string} interval - 采样频率 'game' | 'ui' | 'normal'
   */
  start(callback, interval = 'game') {
    this.onDataCallback = callback
    const intervalMs = this.getIntervalMs(interval)

    console.log('[MockSensor] Starting with mode:', MOCK_CONFIG.mode)

    this.timer = setInterval(() => {
      const data = this.generateData()
      if (this.onDataCallback) {
        this.onDataCallback(data)
      }
    }, intervalMs)

    // 自动交替模式需要额外的定时器
    if (MOCK_CONFIG.mode === 'autoAlternate') {
      this.startAutoAlternate()
    }
  }

  /**
   * 停止 Mock 数据生成
   */
  stop() {
    if (this.timer) {
      clearInterval(this.timer)
      this.timer = null
    }
    if (this.autoAlternateTimer) {
      clearInterval(this.autoAlternateTimer)
      this.autoAlternateTimer = null
    }
    this.onDataCallback = null
    console.log('[MockSensor] Stopped')
  }

  /**
   * 生成模拟的加速度计数据
   * @returns {{ x: number, y: number, z: number, timestamp: number }}
   */
  generateData() {
    let pitch = MOCK_CONFIG.interactive.currentPitch
    let noise = MOCK_CONFIG.interactive.noiseLevel

    // 场景模式
    if (MOCK_CONFIG.mode === 'scenario') {
      const scenario = MOCK_CONFIG.scenarios[MOCK_CONFIG.currentScenario]
      if (scenario) {
        pitch = scenario.pitch
        noise = scenario.noise
      }
    }

    // 添加噪声
    const noiseX = (Math.random() - 0.5) * noise * 2
    const noiseY = (Math.random() - 0.5) * noise * 2
    const noiseZ = (Math.random() - 0.5) * noise * 2

    // 将角度转换为加速度值
    // pitch 角度 → 加速度分量
    const pitchRad = (pitch * Math.PI) / 180
    const gravity = 9.81

    const x = gravity * Math.sin(pitchRad) + noiseX
    const y = gravity * Math.cos(pitchRad) + noiseY
    const z = noiseZ

    return {
      x: parseFloat(x.toFixed(4)),
      y: parseFloat(y.toFixed(4)),
      z: parseFloat(z.toFixed(4)),
      timestamp: Date.now()
    }
  }

  /**
   * 启动自动交替模式
   */
  startAutoAlternate() {
    const pattern = MOCK_CONFIG.autoAlternate.pattern
    const interval = MOCK_CONFIG.autoAlternate.interval

    this.autoAlternateTimer = setInterval(() => {
      const scenarioName = pattern[this.autoAlternateIndex % pattern.length]
      setScenarioMode(scenarioName)
      MOCK_CONFIG.currentScenario = scenarioName
      this.autoAlternateIndex++

      console.log('[MockSensor] Auto alternate to:', scenarioName)
    }, interval)
  }

  /**
   * 设置场景
   * @param {string} scenarioName - 场景名称 'normal' | 'fair' | 'poor'
   */
  setScenario(scenarioName) {
    setScenarioMode(scenarioName)
    MOCK_CONFIG.currentScenario = scenarioName
    console.log('[MockSensor] Set scenario:', scenarioName)
  }

  /**
   * 设置交互模式的角度
   * @param {number} pitch - 角度值
   */
  setPitch(pitch) {
    setInteractiveMode(pitch)
    console.log('[MockSensor] Set pitch:', pitch)
  }

  /**
   * 设置噪声级别
   * @param {number} noise - 噪声级别 (0-1)
   */
  setNoise(noise) {
    MOCK_CONFIG.interactive.noiseLevel = Math.max(0, Math.min(1, noise))
  }

  /**
   * 根据采样频率返回毫秒间隔
   */
  getIntervalMs(interval) {
    switch (interval) {
      case 'game': return 20    // 50Hz
      case 'ui': return 60      // ~16Hz
      case 'normal': return 200 // 5Hz
      default: return MOCK_CONFIG.sampleInterval
    }
  }
}

// 单例
export const mockSensor = new MockSensor()

/**
 * 传感器服务接口封装
 * 统一 Mock 和真实 API 的调用方式
 */

import { MOCK_CONFIG } from '../../config/mock-config'
import { mockSensor } from '../mock/mock-sensor'

// 真实 API 引用（条件导入）
let realSensor = null
if (!MOCK_CONFIG.useMock) {
  try {
    realSensor = require('@system.sensor')
  } catch (e) {
    console.warn('[SensorService] Failed to load real sensor API:', e)
  }
}

class SensorService {
  constructor() {
    this.subscribers = new Map()
    this.isRunning = false
  }

  /**
   * 订阅加速度计数据
   * @param {string} subscriberId - 订阅者 ID
   * @param {Function} callback - 回调函数 { x, y, z, timestamp }
   * @param {string} interval - 采样频率 'game' | 'ui' | 'normal'
   */
  subscribeAccelerometer(subscriberId, callback, interval = 'game') {
    this.subscribers.set(subscriberId, callback)
    console.log('[SensorService] Subscriber added:', subscriberId, 'Total:', this.subscribers.size)

    if (this.isRunning) return

    if (MOCK_CONFIG.useMock) {
      console.log('[SensorService] Using Mock sensor')
      mockSensor.start((data) => {
        this.notifySubscribers(data)
      }, interval)
    } else if (realSensor) {
      console.log('[SensorService] Using real sensor API')
      realSensor.subscribeAccelerometer({
        interval: interval,
        callback: (data) => {
          this.notifySubscribers({
            x: data.x,
            y: data.y,
            z: data.z,
            timestamp: Date.now()
          })
        },
        fail: (data, code) => {
          console.error('[SensorService] Accelerometer error:', code)
        }
      })
    } else {
      console.error('[SensorService] No sensor API available')
      return
    }

    this.isRunning = true
  }

  /**
   * 取消订阅
   * @param {string} subscriberId - 订阅者 ID
   */
  unsubscribeAccelerometer(subscriberId) {
    this.subscribers.delete(subscriberId)
    console.log('[SensorService] Subscriber removed:', subscriberId, 'Total:', this.subscribers.size)

    if (this.subscribers.size === 0) {
      this.stopAccelerometer()
    }
  }

  /**
   * 停止加速度计
   */
  stopAccelerometer() {
    if (MOCK_CONFIG.useMock) {
      mockSensor.stop()
    } else if (realSensor) {
      try {
        realSensor.unsubscribeAccelerometer()
      } catch (e) {
        console.warn('[SensorService] Failed to unsubscribe:', e)
      }
    }
    this.isRunning = false
  }

  /**
   * 通知所有订阅者
   * @param {Object} data - 传感器数据
   */
  notifySubscribers(data) {
    this.subscribers.forEach((callback, id) => {
      try {
        callback(data)
      } catch (e) {
        console.error('[SensorService] Callback error for', id, e)
      }
    })
  }

  /**
   * 获取当前是否正在运行
   * @returns {boolean}
   */
  isAccelerometerRunning() {
    return this.isRunning
  }
}

// 单例
export const sensorService = new SensorService()

/**
 * 存储服务接口封装
 * 使用 @system.storage 键值存储
 */

import storage from '@system.storage'
import { STORAGE_KEYS } from '../../config/constants'

class StorageService {
  /**
   * 保存数据
   * @param {string} key - 存储键
   * @param {*} value - 存储值（会被 JSON 序列化）
   * @returns {Promise<boolean>}
   */
  set(key, value) {
    return new Promise((resolve, reject) => {
      const jsonValue = JSON.stringify(value)
      storage.set({
        key: key,
        value: jsonValue,
        success: () => {
          console.log('[Storage] Saved:', key)
          resolve(true)
        },
        fail: (data, code) => {
          console.error('[Storage] Save failed:', key, code)
          reject(new Error(`Storage set failed: ${code}`))
        }
      })
    })
  }

  /**
   * 读取数据
   * @param {string} key - 存储键
   * @param {*} defaultValue - 默认值
   * @returns {Promise<*>}
   */
  get(key, defaultValue = null) {
    return new Promise((resolve, reject) => {
      storage.get({
        key: key,
        default: '',
        success: (data) => {
          if (data && data !== '') {
            try {
              resolve(JSON.parse(data))
            } catch (e) {
              resolve(defaultValue)
            }
          } else {
            resolve(defaultValue)
          }
        },
        fail: (data, code) => {
          console.error('[Storage] Get failed:', key, code)
          resolve(defaultValue)
        }
      })
    })
  }

  /**
   * 删除数据
   * @param {string} key - 存储键
   * @returns {Promise<boolean>}
   */
  delete(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key: key,
        success: () => {
          console.log('[Storage] Deleted:', key)
          resolve(true)
        },
        fail: (data, code) => {
          console.error('[Storage] Delete failed:', key, code)
          reject(new Error(`Storage delete failed: ${code}`))
        }
      })
    })
  }

  /**
   * 清空所有数据
   * @returns {Promise<boolean>}
   */
  clear() {
    return new Promise((resolve, reject) => {
      storage.clear({
        success: () => {
          console.log('[Storage] Cleared all data')
          resolve(true)
        },
        fail: (data, code) => {
          console.error('[Storage] Clear failed:', code)
          reject(new Error(`Storage clear failed: ${code}`))
        }
      })
    })
  }

  // ========== 便捷方法 ==========

  /**
   * 保存设置
   */
  async saveSettings(settings) {
    return this.set(STORAGE_KEYS.SETTINGS, settings)
  }

  /**
   * 获取设置
   */
  async getSettings() {
    const defaults = {
      sensitivity: 2,          // 1-3
      reminderInterval: 30,    // 分钟
      vibrationStrength: 2,    // 1-3
      language: 'zh-CN'
    }
    return this.get(STORAGE_KEYS.SETTINGS, defaults)
  }

  /**
   * 保存每日数据
   */
  async saveDailyData(date, data) {
    return this.set(`${STORAGE_KEYS.DAILY_PREFIX}${date}`, data)
  }

  /**
   * 获取每日数据
   */
  async getDailyData(date) {
    const defaults = {
      date: date,
      summary: { good: 0, fair: 0, poor: 0, total: 0 },
      timeline: [],
      score: 0
    }
    return this.get(`${STORAGE_KEYS.DAILY_PREFIX}${date}`, defaults)
  }

  /**
   * 保存积分
   */
  async saveScore(scoreData) {
    return this.set(STORAGE_KEYS.SCORE, scoreData)
  }

  /**
   * 获取积分
   */
  async getScore() {
    const defaults = {
      points: 0,
      level: 1,
      badges: [],
      streak: 0
    }
    return this.get(STORAGE_KEYS.SCORE, defaults)
  }
}

// 单例
export const storageService = new StorageService()

/**
 * 振动服务接口封装
 * 使用 @system.vibrator
 */

import vibrator from '@system.vibrator'

class VibratorService {
  /**
   * 短振动
   */
  vibrateShort() {
    vibrator.vibrate({
      mode: 'short',
      success: () => {
        console.log('[Vibrator] Short vibration triggered')
      },
      fail: (data, code) => {
        console.warn('[Vibrator] Short vibration failed:', code)
      }
    })
  }

  /**
   * 长振动
   */
  vibrateLong() {
    vibrator.vibrate({
      mode: 'long',
      success: () => {
        console.log('[Vibrator] Long vibration triggered')
      },
      fail: (data, code) => {
        console.warn('[Vibrator] Long vibration failed:', code)
      }
    })
  }

  /**
   * 自定义振动模式
   * @param {number} duration - 持续时间 (ms)
   * @param {number} interval - 间隔 (ms)
   * @param {number} count - 次数
   */
  vibratePattern(duration = 200, interval = 100, count = 3) {
    vibrator.start({
      duration: duration,
      interval: interval,
      count: count,
      success: (id) => {
        console.log('[Vibrator] Pattern vibration started, id:', id)
      },
      fail: (data, code) => {
        console.warn('[Vibrator] Pattern vibration failed:', code)
      }
    })
  }

  /**
   * 停止振动
   * @param {string} id - 振动任务 ID
   */
  stop(id) {
    vibrator.stop({
      id: id,
      success: () => {
        console.log('[Vibrator] Stopped:', id)
      },
      fail: (data, code) => {
        console.warn('[Vibrator] Stop failed:', code)
      }
    })
  }

  /**
   * 根据强度级别振动
   * @param {number} strength - 强度级别 1-3
   */
  vibrateByStrength(strength) {
    switch (strength) {
      case 1:
        this.vibrateShort()
        break
      case 2:
        this.vibratePattern(150, 80, 2)
        break
      case 3:
        this.vibratePattern(250, 100, 3)
        break
      default:
        this.vibrateShort()
    }
  }
}

// 单例
export const vibratorService = new VibratorService()

