/**
 * 卡尔曼滤波器
 * 用于融合加速度计数据，估算姿态角度
 *
 * 状态向量: [角度, 角速度]
 * 观测量: 加速度计计算的角度
 */

export class KalmanFilter {
  /**
   * @param {Object} options - 配置选项
   * @param {number} options.processNoise - 过程噪声 (默认 0.001)
   * @param {number} options.measurementNoise - 测量噪声 (默认 0.05)
   * @param {number} options.initialAngle - 初始角度 (默认 0)
   */
  constructor(options = {}) {
    const processNoise = options.processNoise || 0.001
    const measurementNoise = options.measurementNoise || 0.05

    // 状态向量 [角度, 角速度]
    this.x = [options.initialAngle || 0, 0]

    // 状态协方差矩阵 P (2x2)
    this.P = [
      [1, 0],
      [0, 1]
    ]

    // 过程噪声协方差矩阵 Q (2x2)
    this.Q = [
      [processNoise, 0],
      [0, processNoise]
    ]

    // 测量噪声协方差 R (标量，简化处理)
    this.R = measurementNoise

    // 状态转移矩阵 F (2x2)
    // 假设单位时间步长，角速度恒定
    this.F = [
      [1, 1],
      [0, 1]
    ]

    // 观测矩阵 H (1x2)
    this.H = [1, 0]

    // 初始化标志
    this.initialized = false
  }

  /**
   * 预测步骤
   * x = F * x
   * P = F * P * F^T + Q
   */
  predict() {
    // 状态预测: x = F * x
    const newX0 = this.F[0][0] * this.x[0] + this.F[0][1] * this.x[1]
    const newX1 = this.F[1][0] * this.x[0] + this.F[1][1] * this.x[1]
    this.x = [newX0, newX1]

    // 协方差预测: P = F * P * F^T + Q
    // 先计算 F * P
    const FP = [
      [this.F[0][0] * this.P[0][0] + this.F[0][1] * this.P[1][0],
       this.F[0][0] * this.P[0][1] + this.F[0][1] * this.P[1][1]],
      [this.F[1][0] * this.P[0][0] + this.F[1][1] * this.P[1][0],
       this.F[1][0] * this.P[0][1] + this.F[1][1] * this.P[1][1]]
    ]

    // 再计算 (F * P) * F^T
    const FPFt = [
      [FP[0][0] * this.F[0][0] + FP[0][1] * this.F[0][1],
       FP[0][0] * this.F[1][0] + FP[0][1] * this.F[1][1]],
      [FP[1][0] * this.F[0][0] + FP[1][1] * this.F[0][1],
       FP[1][0] * this.F[1][0] + FP[1][1] * this.F[1][1]]
    ]

    // 加上过程噪声 Q
    this.P = [
      [FPFt[0][0] + this.Q[0][0], FPFt[0][1] + this.Q[0][1]],
      [FPFt[1][0] + this.Q[1][0], FPFt[1][1] + this.Q[1][1]]
    ]
  }

  /**
   * 更新步骤
   * @param {number} measurement - 测量值（加速度计计算的角度）
   * @returns {number} 滤波后的角度
   */
  update(measurement) {
    // 首次使用时初始化
    if (!this.initialized) {
      this.x = [measurement, 0]
      this.initialized = true
      return measurement
    }

    // 残差: y = z - H * x
    const y = measurement - (this.H[0] * this.x[0] + this.H[1] * this.x[1])

    // 残差协方差: S = H * P * H^T + R
    const S = this.H[0] * (this.P[0][0] * this.H[0] + this.P[0][1] * this.H[1]) +
              this.H[1] * (this.P[1][0] * this.H[0] + this.P[1][1] * this.H[1]) +
              this.R

    // 卡尔曼增益: K = P * H^T * S^-1
    const K = [
      (this.P[0][0] * this.H[0] + this.P[0][1] * this.H[1]) / S,
      (this.P[1][0] * this.H[0] + this.P[1][1] * this.H[1]) / S
    ]

    // 状态更新: x = x + K * y
    this.x[0] += K[0] * y
    this.x[1] += K[1] * y

    // 协方差更新: P = (I - K * H) * P
    const IKH = [
      [1 - K[0] * this.H[0], -K[0] * this.H[1]],
      [-K[1] * this.H[0], 1 - K[1] * this.H[1]]
    ]

    const newP00 = IKH[0][0] * this.P[0][0] + IKH[0][1] * this.P[1][0]
    const newP01 = IKH[0][0] * this.P[0][1] + IKH[0][1] * this.P[1][1]
    const newP10 = IKH[1][0] * this.P[0][0] + IKH[1][1] * this.P[1][0]
    const newP11 = IKH[1][0] * this.P[0][1] + IKH[1][1] * this.P[1][1]

    this.P = [
      [newP00, newP01],
      [newP10, newP11]
    ]

    return this.x[0]
  }

  /**
   * 完整的滤波步骤（预测 + 更新）
   * @param {number} measurement - 测量值
   * @returns {number} 滤波后的角度
   */
  filter(measurement) {
    this.predict()
    return this.update(measurement)
  }

  /**
   * 获取当前角度
   * @returns {number}
   */
  getAngle() {
    return this.x[0]
  }

  /**
   * 获取当前角速度
   * @returns {number}
   */
  getAngularVelocity() {
    return this.x[1]
  }

  /**
   * 重置滤波器
   * @param {number} angle - 初始角度 (默认 0)
   */
  reset(angle = 0) {
    this.x = [angle, 0]
    this.P = [
      [1, 0],
      [0, 1]
    ]
    this.initialized = false
  }
}

/**
 * 从加速度计数据计算俯仰角
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 俯仰角 (度)
 */
export function calculatePitch(ax, ay, az) {
  // 使用 atan2 计算俯仰角
  // 当设备平放时，pitch ≈ 0
  // 当设备前倾时，pitch > 0
  const pitch = Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * 180 / Math.PI
  return pitch
}

/**
 * 从加速度计数据计算横滚角
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 横滚角 (度)
 */
export function calculateRoll(ax, ay, az) {
  const roll = Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * 180 / Math.PI
  return roll
}

/**
 * 姿态判断算法
 * 纯逻辑层，无框架依赖，可独立测试
 */

import { POSTURE_STATUS, DEFAULT_THRESHOLDS } from '../../config/constants'

/**
 * 判断姿态状态
 * @param {number} pitch - 俯仰角 (度)
 * @param {Object} thresholds - 阈值配置
 * @param {number} thresholds.fair - 轻微前倾阈值
 * @param {number} thresholds.poor - 严重前倾阈值
 * @returns {string} 姿态状态
 */
export function classifyPosture(pitch, thresholds = DEFAULT_THRESHOLDS) {
  const absPitch = Math.abs(pitch)

  if (absPitch < thresholds.fair) {
    return POSTURE_STATUS.GOOD
  } else if (absPitch < thresholds.poor) {
    return POSTURE_STATUS.FAIR
  } else {
    return POSTURE_STATUS.POOR
  }
}

/**
 * 获取姿态置信度 (0-100)
 * @param {number} pitch - 俯仰角
 * @param {Object} thresholds - 阈值配置
 * @returns {number} 置信度
 */
export function getPostureConfidence(pitch, thresholds = DEFAULT_THRESHOLDS) {
  const absPitch = Math.abs(pitch)

  if (absPitch < thresholds.fair) {
    // 良好区间：角度越小越好
    return Math.round(100 - (absPitch / thresholds.fair) * 20)
  } else if (absPitch < thresholds.poor) {
    // 注意区间：80-60
    const ratio = (absPitch - thresholds.fair) / (thresholds.poor - thresholds.fair)
    return Math.round(80 - ratio * 20)
  } else {
    // 警告区间：60-0
    const ratio = Math.min((absPitch - thresholds.poor) / 60, 1)
    return Math.round(60 - ratio * 60)
  }
}

/**
 * 判断是否需要提醒
 * @param {string} status - 当前姿态状态
 * @param {string} lastStatus - 上次姿态状态
 * @param {number} reminderInterval - 提醒间隔 (分钟)
 * @param {number} lastReminderTime - 上次提醒时间戳
 * @returns {boolean}
 */
export function shouldRemind(status, lastStatus, reminderInterval, lastReminderTime) {
  // 状态从正常变为异常时提醒
  if (status !== POSTURE_STATUS.GOOD && lastStatus === POSTURE_STATUS.GOOD) {
    return true
  }

  // 严重警告时每次都提醒
  if (status === POSTURE_STATUS.POOR) {
    const now = Date.now()
    const intervalMs = reminderInterval * 60 * 1000
    if (now - lastReminderTime >= intervalMs) {
      return true
    }
  }

  return false
}

/**
 * 计算每日得分
 * @param {Object} summary - 统计数据 { good, fair, poor, total }
 * @returns {number} 得分 (0-100)
 */
export function calculateDailyScore(summary) {
  if (summary.total === 0) return 0

  const goodWeight = 100
  const fairWeight = 60
  const poorWeight = 20

  const weightedSum =
    summary.good * goodWeight +
    summary.fair * fairWeight +
    summary.poor * poorWeight

  return Math.round(weightedSum / summary.total)
}

/**
 * 获取姿态趋势
 * @param {number[]} recentScores - 最近 N 天的得分
 * @returns {string} 'improving' | 'stable' | 'declining'
 */
export function getPostureTrend(recentScores) {
  if (recentScores.length < 2) return 'stable'

  // 计算最近 3 天的平均分
  const recent3 = recentScores.slice(-3)
  const older3 = recentScores.slice(-6, -3)

  if (older3.length === 0) return 'stable'

  const recentAvg = recent3.reduce((a, b) => a + b, 0) / recent3.length
  const olderAvg = older3.reduce((a, b) => a + b, 0) / older3.length

  const diff = recentAvg - olderAvg

  if (diff > 5) return 'improving'
  if (diff < -5) return 'declining'
  return 'stable'
}

/**
 * 滑动窗口平均
 * @param {number[]} data - 数据数组
 * @param {number} windowSize - 窗口大小
 * @returns {number} 平均值
 */
export function slidingWindowAverage(data, windowSize = 5) {
  if (data.length === 0) return 0

  const window = data.slice(-windowSize)
  return window.reduce((a, b) => a + b, 0) / window.length
}

/**
 * 检测异常值 (简单的标准差方法)
 * @param {number[]} data - 数据数组
 * @param {number} threshold - 标准差倍数阈值
 * @returns {boolean} 是否有异常值
 */
export function detectOutliers(data, threshold = 2) {
  if (data.length < 3) return false

  const mean = data.reduce((a, b) => a + b, 0) / data.length
  const variance = data.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) / data.length
  const stdDev = Math.sqrt(variance)

  const lastValue = data[data.length - 1]
  return Math.abs(lastValue - mean) > threshold * stdDev
}

/**
 * Canvas 图表绘制工具
 * 用于在 Canvas 上绘制各种图表
 */

import { POSTURE_COLORS, POSTURE_STATUS } from '../../config/constants'

export class PostureCharts {
  /**
   * @param {Object} ctx - Canvas 2D 上下文
   * @param {number} width - 画布宽度
   * @param {number} height - 画布高度
   */
  constructor(ctx, width, height) {
    this.ctx = ctx
    this.width = width
    this.height = height
  }

  /**
   * 清空画布
   */
  clear() {
    this.ctx.clearRect(0, 0, this.width, this.height)
  }

  /**
   * 绘制环形进度图
   * @param {number} percent - 百分比 (0-100)
   * @param {string} color - 颜色
   * @param {string} label - 标签文字
   * @param {string} valueText - 中心数值文字
   */
  drawRing(percent, color, label, valueText) {
    const centerX = this.width / 2
    const centerY = this.height / 2
    const radius = Math.min(this.width, this.height) / 2 - 20
    const lineWidth = 12

    this.clear()

    // 背景圆环
    this.ctx.beginPath()
    this.ctx.arc(centerX, centerY, radius, 0, Math.PI * 2)
    this.ctx.strokeStyle = '#333333'
    this.ctx.lineWidth = lineWidth
    this.ctx.stroke()

    // 进度圆环
    if (percent > 0) {
      const startAngle = -Math.PI / 2
      const endAngle = startAngle + (Math.PI * 2 * percent / 100)

      this.ctx.beginPath()
      this.ctx.arc(centerX, centerY, radius, startAngle, endAngle)
      this.ctx.strokeStyle = color
      this.ctx.lineWidth = lineWidth
      this.ctx.lineCap = 'round'
      this.ctx.stroke()
    }

    // 中心文字
    this.ctx.fillStyle = '#FFFFFF'
    this.ctx.font = 'bold 32px Arial'
    this.ctx.textAlign = 'center'
    this.ctx.textBaseline = 'middle'
    this.ctx.fillText(valueText || `${Math.round(percent)}`, centerX, centerY - 10)

    // 标签文字
    this.ctx.font = '14px Arial'
    this.ctx.fillStyle = '#9E9E9E'
    this.ctx.fillText(label || '', centerX, centerY + 20)
  }

  /**
   * 绘制多段环形图（饼图样式）
   * @param {Array} segments - 数据段 [{ value, color, label }]
   */
  drawPieRing(segments) {
    const centerX = this.width / 2
    const centerY = this.height / 2
    const radius = Math.min(this.width, this.height) / 2 - 20
    const lineWidth = 12

    this.clear()

    // 背景圆环
    this.ctx.beginPath()
    this.ctx.arc(centerX, centerY, radius, 0, Math.PI * 2)
    this.ctx.strokeStyle = '#333333'
    this.ctx.lineWidth = lineWidth
    this.ctx.stroke()

    // 计算总值
    const total = segments.reduce((sum, seg) => sum + seg.value, 0)
    if (total === 0) return

    // 绘制各段
    let startAngle = -Math.PI / 2
    segments.forEach(seg => {
      if (seg.value > 0) {
        const sweepAngle = (seg.value / total) * Math.PI * 2

        this.ctx.beginPath()
        this.ctx.arc(centerX, centerY, radius, startAngle, startAngle + sweepAngle)
        this.ctx.strokeStyle = seg.color
        this.ctx.lineWidth = lineWidth
        this.ctx.lineCap = 'round'
        this.ctx.stroke()

        startAngle += sweepAngle
      }
    })
  }

  /**
   * 绘制时间线条形图
   * @param {Array} data - 数据 [{ status, duration }]
   * @param {number} y - Y 坐标
   * @param {number} height - 条形高度
   */
  drawTimeline(data, y, height = 16) {
    if (!data || data.length === 0) return

    const totalDuration = data.reduce((sum, item) => sum + item.duration, 0)
    if (totalDuration === 0) return

    let x = 0
    const segmentWidth = this.width / data.length

    data.forEach((item, index) => {
      const color = POSTURE_COLORS[item.status] || POSTURE_COLORS[POSTURE_STATUS.UNKNOWN]
      const width = (item.duration / totalDuration) * this.width

      this.ctx.fillStyle = color
      this.ctx.fillRect(x, y, width - 2, height)

      x += width
    })
  }

  /**
   * 绘制折线图
   * @param {number[]} data - 数据点数组
   * @param {Object} options - 配置选项
   */
  drawLineChart(data, options = {}) {
    const {
      x = 0,
      y = 0,
      width = this.width,
      height = this.height / 2,
      lineColor = '#4CAF50',
      fillColor = 'rgba(76, 175, 80, 0.2)',
      lineWidth = 2,
      showPoints = true,
      pointRadius = 3
    } = options

    if (!data || data.length === 0) return

    // 找出最大最小值
    const max = Math.max(...data)
    const min = Math.min(...data)
    const range = max - min || 1

    // 计算点的坐标
    const points = data.map((val, i) => ({
      x: x + (i / (data.length - 1)) * width,
      y: y + height - ((val - min) / range) * height
    }))

    // 绘制填充区域
    this.ctx.beginPath()
    this.ctx.moveTo(points[0].x, y + height)
    points.forEach(p => this.ctx.lineTo(p.x, p.y))
    this.ctx.lineTo(points[points.length - 1].x, y + height)
    this.ctx.closePath()
    this.ctx.fillStyle = fillColor
    this.ctx.fill()

    // 绘制线条
    this.ctx.beginPath()
    this.ctx.moveTo(points[0].x, points[0].y)
    for (let i = 1; i < points.length; i++) {
      this.ctx.lineTo(points[i].x, points[i].y)
    }
    this.ctx.strokeStyle = lineColor
    this.ctx.lineWidth = lineWidth
    this.ctx.stroke()

    // 绘制点
    if (showPoints) {
      points.forEach(p => {
        this.ctx.beginPath()
        this.ctx.arc(p.x, p.y, pointRadius, 0, Math.PI * 2)
        this.ctx.fillStyle = lineColor
        this.ctx.fill()
      })
    }
  }

  /**
   * 绘制柱状图
   * @param {Array} data - 数据 [{ value, color }]
   * @param {Object} options - 配置选项
   */
  drawBarChart(data, options = {}) {
    const {
      x = 0,
      y = 0,
      width = this.width,
      height = this.height / 2,
      barColor = '#4CAF50',
      gap = 4
    } = options

    if (!data || data.length === 0) return

    const max = Math.max(...data.map(d => d.value))
    const barWidth = (width - gap * (data.length - 1)) / data.length

    data.forEach((item, i) => {
      const barHeight = (item.value / max) * height
      const barX = x + i * (barWidth + gap)
      const barY = y + height - barHeight

      this.ctx.fillStyle = item.color || barColor
      this.ctx.fillRect(barX, barY, barWidth, barHeight)
    })
  }
}

