/**
 * 姿态判断算法 - 纯逻辑，无框架依赖
 * 可在 Node.js 环境下单元测试
 */

import { POSTURE_STATUS, DEFAULT_THRESHOLDS } from '../../config/constants'

/**
 * 从加速度数据计算俯仰角
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 俯仰角 (度)
 */
export function calculatePitch(ax, ay, az) {
  const pitch = Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * 180 / Math.PI
  return pitch
}

/**
 * 从加速度数据计算横滚角
 * @param {number} ax - X轴加速度
 * @param {number} ay - Y轴加速度
 * @param {number} az - Z轴加速度
 * @returns {number} 横滚角 (度)
 */
export function calculateRoll(ax, ay, az) {
  const roll = Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * 180 / Math.PI
  return roll
}

/**
 * 判断姿态状态
 * @param {number} pitch - 俯仰角
 * @param {Object} thresholds - 阈值配置
 * @returns {string} 姿态状态
 */
export function classifyPosture(pitch, thresholds = DEFAULT_THRESHOLDS) {
  const absPitch = Math.abs(pitch)

  if (absPitch < thresholds.fair) {
    return POSTURE_STATUS.GOOD
  } else if (absPitch < thresholds.poor) {
    return POSTURE_STATUS.FAIR
  } else {
    return POSTURE_STATUS.POOR
  }
}

/**
 * 获取姿态对应的中文描述
 * @param {string} status - 姿态状态
 * @returns {string} 中文描述
 */
export function getPostureLabel(status) {
  const labels = {
    [POSTURE_STATUS.GOOD]: '坐姿良好',
    [POSTURE_STATUS.FAIR]: '注意坐姿',
    [POSTURE_STATUS.POOR]: '坐姿不佳',
    [POSTURE_STATUS.UNKNOWN]: '未知'
  }
  return labels[status] || labels[POSTURE_STATUS.UNKNOWN]
}

/**
 * 获取姿态对应的颜色
 * @param {string} status - 姿态状态
 * @returns {string} 颜色值
 */
export function getPostureColor(status) {
  const colors = {
    [POSTURE_STATUS.GOOD]: '#4CAF50',
    [POSTURE_STATUS.FAIR]: '#FF9800',
    [POSTURE_STATUS.POOR]: '#F44336',
    [POSTURE_STATUS.UNKNOWN]: '#9E9E9E'
  }
  return colors[status] || colors[POSTURE_STATUS.UNKNOWN]
}

/**
 * 获取姿态对应的 Emoji
 * @param {string} status - 姿态状态
 * @returns {string} Emoji
 */
export function getPostureEmoji(status) {
  const emojis = {
    [POSTURE_STATUS.GOOD]: '😊',
    [POSTURE_STATUS.FAIR]: '😐',
    [POSTURE_STATUS.POOR]: '😟',
    [POSTURE_STATUS.UNKNOWN]: '❓'
  }
  return emojis[status] || emojis[POSTURE_STATUS.UNKNOWN]
}

/**
 * 计算姿态得分 (0-100)
 * @param {Object} summary - 统计数据 { good, fair, poor, total }
 * @returns {number} 得分
 */
export function calculateScore(summary) {
  if (!summary || summary.total === 0) return 0

  const { good, fair, poor, total } = summary
  // 良好 +10分，注意 +5分，警告 +0分
  const score = (good * 10 + fair * 5) / (total * 10) * 100
  return Math.round(score)
}

